        public static float2x2 BezierCurve(in float2x2 from, in float2x2 to, in float2x2 fromTangent, in float2x2 toTangent, float t)
        {
            var u = 1f - t;
            var tt = t * t;
            var uu = u * u;
            var ttt = tt * t;
            var uuu = uu * u;

            return uuu * from +
                (3 * uu * t * fromTangent) +
                (3 * u * tt * toTangent) +
                ttt * to;
        }

        public static float2x2 BezierTangent(in float2x2 from, in float2x2 to, in float2x2 fromTangent, in float2x2 toTangent, float t)
        {
            return -3f * MathX.Pow(1f - t, 2f) * from +
                3f * MathX.Pow(1f - t, 2f) * fromTangent -
                6f * t * (1f - t) * fromTangent -
                3f * MathX.Pow(t, 2f) * toTangent +
                6f * t * (1f - t) * toTangent +
                3f * MathX.Pow(t, 2f) * to;
        }
	}

