			angle *= MathX.Deg2Rad;

			var sin = MathX.Sin(angle);
			var cos = MathX.Cos(angle);

			return new double2x2(
				cos, -sin,
				sin, cos   );
		}

		public readonly double Determinant => m00*m11 - m10 * m01;

		public readonly double2x2 Inverse
		{
			get
			{
				var det = Determinant;

				if(det == 0)
					return double2x2.Zero;

				det = 1f / det;

				return new double2x2(
					m11 * det,
					-m01 * det,
					-m10 * det,
					m00 * det
				);
			}
		}

		
