		public readonly double[] ToArray()
		{
			var array = new double[4];
			FillArray(array);
			return array;
		}

		public readonly void FillArray(double[] array, int offset = 0)
		{
			if(array.Length - offset < 4)
				throw new Exception("Array doesn't have sufficient capacity for the whole matrix");

			array[offset+0] = m00;
			array[offset+1] = m01;
			array[offset+2] = m10;
			array[offset+3] = m11;
		}

		public readonly double[,] To2DArray()
		{
			var array = new double[2,2];
			Fill2DArray(array);
			return array;
		}

		public readonly void Fill2DArray(double[,] array, int offset0 = 0, int offset1 = 0)
		{
			if(array.GetLength(0) - offset0 < 2 || array.GetLength(1) - offset1 < 2)
				throw new Exception("Array doesn't have sufficient capacity for the whole matrix");

			for(int r = 0; r < 2; r++)
				for(int c = 0; c < 2; c++)
					array[offset0+r, offset1+c] = this[r,c];
		}

