		public static double2x2 Parse(string s, NumberStyles style, IFormatProvider provider)
		{
			var nums = PrimitivesUtility.ExtractElements(s, 4);

			return new double2x2(double.Parse(nums[0], style, provider),double.Parse(nums[1], style, provider),double.Parse(nums[2], style, provider),double.Parse(nums[3], style, provider));
		}

        public static bool TryParse(string s, out double2x2 val)
        {
            return TryParse(s, NumberStyles.Float, null, out val);
        }

        public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out double2x2 val)
	    {
            var nums = PrimitivesUtility.ExtractElements(s, 4);

			if(nums == null)
			{
				val = default;
				return false;
			}

            var parsed_m00 = double.TryParse(nums[0], numberStyles, formatProvider, out double m00);
		var parsed_m01 = double.TryParse(nums[1], numberStyles, formatProvider, out double m01);
		var parsed_m10 = double.TryParse(nums[2], numberStyles, formatProvider, out double m10);
		var parsed_m11 = double.TryParse(nums[3], numberStyles, formatProvider, out double m11);         

            if(parsed_m00 && parsed_m01 && parsed_m10 && parsed_m11)
            {
                val = new double2x2(m00,m01,m10,m11);
                return true;
            }

            val = default;
            return false;
	    }

