	public static partial class MathX
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double2x2 Lerp(in double2x2 a, in double2x2 b, float lerp)
		{
			if(lerp <= 0)
				return a;
			if(lerp >= 1)
				return b;

			return LerpUnclamped(a, b, lerp);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double2x2 LerpUnclamped(in double2x2 a, in double2x2 b, float lerp)
		{
			return a + (b - a) * lerp;
		}

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double2x2 ConstantLerp(in double2x2 a, in double2x2 b, float delta)
		{
            // TODO!!! This just applies constant lerp individually to each element, so it's done element-wise
            // Should there be a different variant where it computes distance in the multidimensional space and
            // lerps each component appropriately?
			return new double2x2(
				ConstantLerp(a.m00, b.m00, delta),
				ConstantLerp(a.m01, b.m01, delta),
				ConstantLerp(a.m10, b.m10, delta),
				ConstantLerp(a.m11, b.m11, delta));
		}

        
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
		    public static double2x2 Lerp(in double2x2 a, in double2x2 b, double lerp)
		    {
			    if(lerp <= 0)
				    return a;
			    if(lerp >= 1)
				    return b;

			    return LerpUnclamped(a, b, lerp);
		    }

		    [MethodImpl(MethodImplOptions.AggressiveInlining)]
		    public static double2x2 LerpUnclamped(in double2x2 a, in double2x2 b, double lerp)
		    {
			    return a + (b - a) * lerp;
		    }

            
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
