        public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out float3x3 val)
	    {
            var nums = PrimitivesUtility.ExtractElements(s, 9);

			if(nums == null)
			{
				val = default;
				return false;
			}

            var parsed_m00 = float.TryParse(nums[0], numberStyles, formatProvider, out float m00);
		var parsed_m01 = float.TryParse(nums[1], numberStyles, formatProvider, out float m01);
		var parsed_m02 = float.TryParse(nums[2], numberStyles, formatProvider, out float m02);
		var parsed_m10 = float.TryParse(nums[3], numberStyles, formatProvider, out float m10);
		var parsed_m11 = float.TryParse(nums[4], numberStyles, formatProvider, out float m11);
		var parsed_m12 = float.TryParse(nums[5], numberStyles, formatProvider, out float m12);
		var parsed_m20 = float.TryParse(nums[6], numberStyles, formatProvider, out float m20);
		var parsed_m21 = float.TryParse(nums[7], numberStyles, formatProvider, out float m21);
		var parsed_m22 = float.TryParse(nums[8], numberStyles, formatProvider, out float m22);         

            if(parsed_m00 && parsed_m01 && parsed_m02 && parsed_m10 && parsed_m11 && parsed_m12 && parsed_m20 && parsed_m21 && parsed_m22)
            {
                val = new float3x3(m00,m01,m02,m10,m11,m12,m20,m21,m22);
                return true;
            }

            val = default;
            return false;
	    }

