			return new float3(m.m00*v.x+m.m01*v.y+m.m02*v.z , m.m10*v.x+m.m11*v.y+m.m12*v.z , m.m20*v.x+m.m21*v.y+m.m22*v.z);
		}

		
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float2 operator *(in float3x3 m, in float2 v)
			{
				
				var result = (m * (new float3(v.xy, 1)));
				return result.xy / result.z;
			}

			
                    public readonly float3 TransformVector(in float3 vector)
			{
				return new float3(m00*vector.x + m01*vector.y + m02*vector.z,
						m10*vector.x + m11*vector.y + m12*vector.z,
						m20*vector.x + m21*vector.y + m22*vector.z);
			}

            public readonly float TransformScale(float scale) =>
                TransformVector(scale * float3.UnitDiagonal).Magnitude;

			public readonly float3 TransformDirection(in float3 direction)
			{
				return TransformVector(direction).Normalized * direction.Magnitude;
			}
            
		
