			public readonly double Determinant
			{
				get
				{
					return 
						m00 * (m11*m22 - m12*m21) -
						m01 * (m10*m22 - m12*m20) +
						m02 * (m10*m21 - m11*m20);
				}
			}


			public readonly double3x3 Inverse
			{
				get
				{
					var det = Determinant;

					if(det == 0)
						return double3x3.Zero;

					det = 1 / det;

					return new double3x3(
						m00: (m11 * m22 - m12 * m21) * det,
						m01: (m02 * m21 - m22 * m01) * det,
						m02: (m01 * m12 - m11 * m02) * det,

						m10: (m12 * m20 - m10 * m22) * det,
						m11: (m00 * m22 - m02 * m20) * det,
						m12: (m02 * m10 - m00 * m12) * det,

						m20: (m10 * m21 - m11 * m20) * det,
						m21: (m01 * m20 - m00 * m21) * det,
						m22: (m00 * m11 - m01 * m10) * det
					);
				}
			}

