			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double3x3 Rotation(in doubleQ q)
			{
				var x = q.x;
				var y = q.y;
				var z = q.z;
				var w = q.w;

				var xx = 2*x*x;
				var yy = 2*y*y;
				var zz = 2*z*z;

				var xy = 2*x*y;
				var wz = 2*w*z;
				var xz = 2*x*z;
				var wy = 2*w*y;
				var yz = 2*y*z;
				var wx = 2*w*x;

				return new double3x3(
					m00: (1-yy-zz),	m01: (xy-wz),	m02: (xz+wy),
					m10: (xy+wz),	m11: (1-xx-zz),	m12: (yz-wx),
					m20: (xz-wy),	m21: (yz+wx),	m22: (1-xx-yy)
					);
			}
			
			public static double3x3 ScaleRotation(in double3 scale, in doubleQ rotation)
			{
				var x = rotation.x;
				var y = rotation.y;
				var z = rotation.z;
				var w = rotation.w;

				var xx = 2*x*x;
				var yy = 2*y*y;
				var zz = 2*z*z;

				var xy = 2*x*y;
				var wz = 2*w*z;
				var xz = 2*x*z;
				var wy = 2*w*y;
				var yz = 2*y*z;
				var wx = 2*w*x;

				var sx = scale.x;
				var sy = scale.y;
				var sz = scale.z;

				return new double3x3(
					m00: sx*(1-yy-zz),	m01: sy*(xy-wz),	m02: sz*(xz+wy),
					m10: sx*(xy+wz),	m11: sy*(1-xx-zz),	m12: sz*(yz-wx),
					m20: sx*(xz-wy),	m21: sy*(yz+wx),	m22: sz*(1-xx-yy)
					);
			} 

			public readonly double3 DecomposedScale
			{
				get
				{
					return new double3(
						MathX.Sqrt(m00*m00 + m10*m10 + m20*m20) /** MathX.Sign(Determinant)*/,
						MathX.Sqrt(m01*m01 + m11*m11 + m21*m21),
						MathX.Sqrt(m02*m02 + m12*m12 + m22*m22)
						);
				}
			}

			public readonly doubleQ DecomposedRotation
			{
				get
				{
					var m1 = (new double3(m01, m11, m21)).Normalized;
					var m2 = (new double3(m02, m12, m22)).Normalized;
					var m0 = MathX.Cross(m1, m2);

					var r0 = m0.x + m1.y + m2.z;

					double x, y, z, w;

					if (r0 > 0)
					{
						var r1 = MathX.Sqrt(r0 + 1f);
						w = r1 * 0.5f;
						r1 = 0.5f / r1;
						x = (m1.z - m2.y) * r1;
						y = (m2.x - m0.z) * r1;
						z = (m0.y - m1.x) * r1;
					}
					else if((m0.x >= m1.y) && (m0.x >= m2.z))
					{
						var r1 = MathX.Sqrt(((1f + m0.x) - m1.y) - m2.z);
						var r2 = 0.5f / r1;
						x = 0.5f * r1;
						y = (m0.y + m1.x) * r2;
						z = (m0.z + m2.x) * r2;
						w = (m1.z - m2.y) * r2;
					}
					else if (m1.y > m2.z)
					{
						var r1 = MathX.Sqrt(((1f + m1.y) - m0.x) - m2.z);
						var r2 = 0.5f / r1;
						x = (m1.x + m0.y) * r2;
						y = 0.5f * r1;
						z = (m2.y + m1.z) * r2;
						w = (m2.x - m0.z) * r2;
					}
					else
					{
						var r1 = MathX.Sqrt(((1f + m2.z) - m0.x) - m1.y);
						var r2 = 0.5f / r1;
						x = (m2.x + m0.z) * r2;
						y = (m2.y + m1.z) * r2;
						z = 0.5f * r1;
						w = (m0.y - m1.x) * r2;
					}

					return new doubleQ(x,y,z,w);
				}
			}

			
