		public readonly void FillArray(double[] array, int offset = 0)
		{
			if(array.Length - offset < 9)
				throw new Exception("Array doesn't have sufficient capacity for the whole matrix");

			array[offset+0] = m00;
			array[offset+1] = m01;
			array[offset+2] = m02;
			array[offset+3] = m10;
			array[offset+4] = m11;
			array[offset+5] = m12;
			array[offset+6] = m20;
			array[offset+7] = m21;
			array[offset+8] = m22;
		}

		public readonly double[,] To2DArray()
		{
			var array = new double[3,3];
			Fill2DArray(array);
			return array;
		}

		public readonly void Fill2DArray(double[,] array, int offset0 = 0, int offset1 = 0)
		{
			if(array.GetLength(0) - offset0 < 3 || array.GetLength(1) - offset1 < 3)
				throw new Exception("Array doesn't have sufficient capacity for the whole matrix");

			for(int r = 0; r < 3; r++)
				for(int c = 0; c < 3; c++)
					array[offset0+r, offset1+c] = this[r,c];
		}

