			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static void SetTransform(in float3 position, in floatQ rotation, in float3 scale,
				out float4x4 matrix)
			{
				var x = rotation.x;
				var y = rotation.y;
				var z = rotation.z;
				var w = rotation.w;

				var xx = 2*x*x;
				var yy = 2*y*y;
				var zz = 2*z*z;

				var xy = 2*x*y;
				var wz = 2*w*z;
				var xz = 2*x*z;
				var wy = 2*w*y;
				var yz = 2*y*z;
				var wx = 2*w*x;

				var sx = scale.x;
				var sy = scale.y;
				var sz = scale.z;

				matrix = new float4x4(
					sx*(1-yy-zz),	sy*(xy-wz),	sz*(xz+wy),	position.x,
					sx*(xy+wz),	sy*(1-xx-zz),	sz*(yz-wx),	position.y,
					sx*(xz-wy),	sy*(yz+wx),	sz*(1-xx-yy),	position.z,
					0, 0, 0, 1
				);

				// Unoptimized:
				/*return new float4x4(
					sx*(1-2*yy-2*zz),	sy*(2*x*y-2*w*z),	sz*(2*x*z+2*w*y),	position.x,
					sx*(2*x*y+2*w*z),	sy*(1-2*xx-2*zz),	sz*(2*y*z-2*w*x),	position.y,
					sx*(2*x*z-2*w*y),	sy*(2*y*z+2*w*x),	sz*(1-2*xx-2*yy),	position.z,
					0, 0, 0, 1
				);*/
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float4x4 Transform(in float3 position, in floatQ rotation, in float3 scale)
			{
				var x = rotation.x;
				var y = rotation.y;
				var z = rotation.z;
				var w = rotation.w;

				var xx = 2*x*x;
				var yy = 2*y*y;
				var zz = 2*z*z;

				var xy = 2*x*y;
				var wz = 2*w*z;
				var xz = 2*x*z;
				var wy = 2*w*y;
				var yz = 2*y*z;
				var wx = 2*w*x;

				var sx = scale.x;
				var sy = scale.y;
				var sz = scale.z;

				return new float4x4(
					sx*(1-yy-zz),	sy*(xy-wz),	sz*(xz+wy),	position.x,
					sx*(xy+wz),	sy*(1-xx-zz),	sz*(yz-wx),	position.y,
					sx*(xz-wy),	sy*(yz+wx),	sz*(1-xx-yy),	position.z,
					0, 0, 0, 1
				);

				// Unoptimized:
				/*return new float4x4(
					sx*(1-2*yy-2*zz),	sy*(2*x*y-2*w*z),	sz*(2*x*z+2*w*y),	position.x,
					sx*(2*x*y+2*w*z),	sy*(1-2*xx-2*zz),	sz*(2*y*z-2*w*x),	position.y,
					sx*(2*x*z-2*w*y),	sy*(2*y*z+2*w*x),	sz*(1-2*xx-2*yy),	position.z,
					0, 0, 0, 1
				);*/
			}

			public readonly float3 DecomposedPosition => new float3(m03, m13, m23);

			public readonly void Decompose(out float3 position, out floatQ rotation, out float3 scale)
			{
				position = new float3(m03, m13, m23);

				scale = new float3(
						MathX.Sqrt(m00*m00 + m10*m10 + m20*m20) /** MathX.Sign(Determinant3x3)*/,
						MathX.Sqrt(m01*m01 + m11*m11 + m21*m21),
						MathX.Sqrt(m02*m02 + m12*m12 + m22*m22)
						);

				var invScale = 1 / scale;

				//var m0 = new float3(m00, m10, m20) * invScale.x;
				var m1 = new float3(m01, m11, m21) * invScale.y;
				var m2 = new float3(m02, m12, m22) * invScale.z;

				var m0 = MathX.Cross(m1, m2);

				var r0 = m0.x + m1.y + m2.z;

				float x, y, z, w;

				if (r0 > 0)
				{
					var r1 = MathX.Sqrt(r0 + 1f);
					w = r1 * 0.5f;
					r1 = 0.5f / r1;
					x = (m1.z - m2.y) * r1;
					y = (m2.x - m0.z) * r1;
					z = (m0.y - m1.x) * r1;
				}
				else if((m0.x >= m1.y) && (m0.x >= m2.z))
				{
					var r1 = MathX.Sqrt(((1f + m0.x) - m1.y) - m2.z);
					var r2 = 0.5f / r1;
					x = 0.5f * r1;
					y = (m0.y + m1.x) * r2;
					z = (m0.z + m2.x) * r2;
					w = (m1.z - m2.y) * r2;
				}
				else if (m1.y > m2.z)
				{
					var r1 = MathX.Sqrt(((1f + m1.y) - m0.x) - m2.z);
					var r2 = 0.5f / r1;
					x = (m1.x + m0.y) * r2;
					y = 0.5f * r1;
					z = (m2.y + m1.z) * r2;
					w = (m2.x - m0.z) * r2;
				}
				else
				{
					var r1 = MathX.Sqrt(((1f + m2.z) - m0.x) - m1.y);
					var r2 = 0.5f / r1;
					x = (m2.x + m0.z) * r2;
					y = (m2.y + m1.z) * r2;
					z = 0.5f * r1;
					w = (m0.y - m1.x) * r2;
				}

				rotation = new floatQ(x,y,z,w);
			}

			
			
			

