			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float4x4 Rotation(in floatQ q)
			{
				var x = q.x;
				var y = q.y;
				var z = q.z;
				var w = q.w;

				var xx = 2*x*x;
				var yy = 2*y*y;
				var zz = 2*z*z;

				var xy = 2*x*y;
				var wz = 2*w*z;
				var xz = 2*x*z;
				var wy = 2*w*y;
				var yz = 2*y*z;
				var wx = 2*w*x;

				return new float4x4(
					m00: (1-yy-zz),	m01: (xy-wz),	m02: (xz+wy),
					m10: (xy+wz),	m11: (1-xx-zz),	m12: (yz-wx),
					m20: (xz-wy),	m21: (yz+wx),	m22: (1-xx-yy)
					 , m33: 1 );
			}
			
			public static float4x4 ScaleRotation(in float3 scale, in floatQ rotation)
			{
				var x = rotation.x;
				var y = rotation.y;
				var z = rotation.z;
				var w = rotation.w;

				var xx = 2*x*x;
				var yy = 2*y*y;
				var zz = 2*z*z;

				var xy = 2*x*y;
				var wz = 2*w*z;
				var xz = 2*x*z;
				var wy = 2*w*y;
				var yz = 2*y*z;
				var wx = 2*w*x;

				var sx = scale.x;
				var sy = scale.y;
				var sz = scale.z;

				return new float4x4(
					m00: sx*(1-yy-zz),	m01: sy*(xy-wz),	m02: sz*(xz+wy),
					m10: sx*(xy+wz),	m11: sy*(1-xx-zz),	m12: sz*(yz-wx),
					m20: sx*(xz-wy),	m21: sy*(yz+wx),	m22: sz*(1-xx-yy)
					 , m33: 1 );
			} 

