						m20*vector.x + m21*vector.y + m22*vector.z);
			}

            public readonly float TransformScale(float scale) =>
                TransformVector(scale * float3.UnitDiagonal).Magnitude;

			public readonly float3 TransformDirection(in float3 direction)
			{
				return TransformVector(direction).Normalized * direction.Magnitude;
