				m20*matrix.m00 + m21*matrix.m10 + m22*matrix.m20,
				m20*matrix.m01 + m21*matrix.m11 + m22*matrix.m21,
				m20*matrix.m02 + m21*matrix.m12 + m22*matrix.m22
