	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double4x4 Lerp(in double4x4 a, in double4x4 b, float lerp)
		{
			if(lerp <= 0)
				return a;
			if(lerp >= 1)
				return b;

			return LerpUnclamped(a, b, lerp);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double4x4 LerpUnclamped(in double4x4 a, in double4x4 b, float lerp)
		{
			return a + (b - a) * lerp;
		}

