				ConstantLerp(a.m12, b.m12, delta),
				ConstantLerp(a.m13, b.m13, delta),
				ConstantLerp(a.m20, b.m20, delta),
				ConstantLerp(a.m21, b.m21, delta),
				ConstantLerp(a.m22, b.m22, delta),
				ConstantLerp(a.m23, b.m23, delta),
				ConstantLerp(a.m30, b.m30, delta),
				ConstantLerp(a.m31, b.m31, delta),
				ConstantLerp(a.m32, b.m32, delta),
				ConstantLerp(a.m33, b.m33, delta));
		}

        
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
		    public static double4x4 Lerp(in double4x4 a, in double4x4 b, double lerp)
		    {
			    if(lerp <= 0)
				    return a;
			    if(lerp >= 1)
				    return b;

			    return LerpUnclamped(a, b, lerp);
		    }

		    [MethodImpl(MethodImplOptions.AggressiveInlining)]
		    public static double4x4 LerpUnclamped(in double4x4 a, in double4x4 b, double lerp)
		    {
			    return a + (b - a) * lerp;
		    }

            
